async function skillToolHarness(
  skills: Array<LoadedSkill | SkillDefinition>,
  options: {
    files?: Record<string, string | Buffer>;
    skillConfig?: Record<string, Record<string, unknown>>;
    skillEvolutionStore?: SkillEvolutionStore;
    visibleNames?: string[];
  } = {}
): Promise<{ run(toolName: string, input: Record<string, unknown>): Promise<ToolResult> }> {
  const root = await mkdtemp(join(tmpdir(), "skill-tools-test-"));
  const registry = new SkillRegistry();
  for (const skill of skills) {
    if (isLoadedSkill(skill)) {
      const skillRoot = join(root, skill.name);
      await mkdir(skillRoot, { recursive: true });
      await writeFile(join(skillRoot, "SKILL.md"), "{}", "utf8");
      for (const [path, content] of Object.entries(options.files ?? {})) {
        const absolute = join(skillRoot, path);
        await mkdir(dirname(absolute), { recursive: true });
        await writeFile(absolute, content);
      }
      registry.register({
        ...skill,
        sourcePath: join(skillRoot, "SKILL.md"),
        sourceRoot: root,
        resources: skill.resources ?? Object.keys(options.files ?? {}).map((path) => ({
          kind: "reference" as const,
          path
        }))
      });
    } else {
      registry.register(skill);
    }
  }
  const visibleRegistry = options.visibleNames === undefined ? undefined : new SkillRegistry();
  for (const name of options.visibleNames ?? []) {
    const skill = registry.get(name);
    if (skill !== undefined) visibleRegistry!.register(skill);
  }
  const tools = createSkillTools({
    registry,
    visibleRegistry,
    localSkillsRoot: root,
    skillConfig: options.skillConfig,
    skillEvolutionStore: options.skillEvolutionStore
  });
  return {
    async run(toolName, input) {
      const tool = tools.find((candidate) => candidate.name === toolName);
      if (tool === undefined) {
        throw new Error(`${toolName} was not registered`);
      }
      return await tool.run(input);
    }
  };
}

type ParsedSkillSearchPayload = {
  name: string;
  query: string;
  maxResults: number;
  results: Array<{
    path: string;
    excerpt: string;
    heading?: string;
    line?: number;
    truncated?: boolean;
  }>;
  matchCount: number;
  truncated: boolean;
  skippedResources?: Array<{ path: string; reason: string }>;
};

function parseSearchPayload(result: ToolResult): ParsedSkillSearchPayload {
  expect(result.ok).toBe(true);
  return JSON.parse(result.content) as ParsedSkillSearchPayload;
}

async function expectSearchFailure(
  harness: { run(toolName: "skill.search", input: Record<string, unknown>): Promise<ToolResult> },
  input: Record<string, unknown>,
  message: string
): Promise<void> {
  const result = await harness.run("skill.search", input);
  expect(result.ok).toBe(false);
  expect(result.content).toContain(message);
}

function loadedSkill(overrides: Partial<LoadedSkill> = {}): LoadedSkill {
  const name = overrides.name ?? "loaded-skill";
  return {
    name,
    description: `Test skill ${name}.`,
    version: "0.1.0",
    category: "general",
    whenToUse: [],
    requiredToolsets: [],
    playbook: [],
    permissionExpectations: [],
    examples: [],
    evaluations: [],
    sourcePath: join(tmpdir(), name, "SKILL.md"),
    sourceKind: "local",
    sourceRoot: tmpdir(),
    instructions: "# Instructions\n\nUse the skill.",
    ...overrides
  };
}

function largeInstructions(): string {
  return [
    "# Large",
    "Detailed instructions.\n".repeat(420),
    "LARGE_ROOT_TAIL_MARKER"
  ].join("\n");
}

function routerForSkill(
  skill: LoadedSkill | SkillDefinition,
  skillConfig: Record<string, Record<string, unknown>>
): RuntimeRouter {
  const route: IntentRoute = {
    nativeIntent: "general",
    labels: ["general"],
    confidence: 1,
    suggestedToolsets: [],
    suggestedSkills: [skill],
    confirmationRequired: false,
    evidence: [],
    rationale: "test"
  };
  const intentRouter = {
    route: () => route
  } as unknown as IntentRouter;
  return new RuntimeRouter({
    intentRouter,
    skillConfig
  });
}

function isLoadedSkill(skill: LoadedSkill | SkillDefinition): skill is LoadedSkill {
  return "instructions" in skill && "sourcePath" in skill;
}


describe("session skill inspection visibility", () => {
  it.each(["skill.read", "skill.view", "skill.inspect", "skill.search", "skill.eval", "skill.export", "skill.usage", "skill.list_proposals", "skill.review_proposals"])("%s cannot distinguish a hidden skill from an unknown skill", async (toolName) => {
    const root = await mkdtemp(join(tmpdir(), "skill-visibility-"));
    const store = new SkillEvolutionStore({ usagePath: join(root, "usage.json"), evolutionRoot: join(root, "evolution") });
    const viewed = vi.spyOn(store, "recordSkillViewed");
    const usage = vi.spyOn(store, "getUsage");
    const input = { name: "hidden", query: "secret", resource: "references/secret.md" };
    const hidden = await skillToolHarness([loadedSkill({ name: "hidden", instructions: "private instructions" })], { visibleNames: [], skillEvolutionStore: store, files: { "references/secret.md": "private file" } });
    const absent = await skillToolHarness([], { visibleNames: [], skillEvolutionStore: store });
    const result = await hidden.run(toolName, input);
    expect(result).toEqual(await absent.run(toolName, input));
    expect(result.ok).toBe(false);
    expect(JSON.stringify(result)).not.toContain("private");
    expect(viewed).not.toHaveBeenCalled();
    expect(usage).not.toHaveBeenCalled();
  });

